#include <cstdint>
#include <vector>

struct Write { std::uint64_t address; std::uint64_t length; };

int firstHit(const std::vector<Write>& writes, std::uint64_t watch, std::uint64_t size)
{
    for (std::size_t i{ 0 }; i < writes.size(); ++i)
    {
        const Write& w{ writes[i] };
        if (w.length == 0 || size == 0) continue;
        // [a, a + n) and [b, b + m) overlap when each starts before the other ends.
        if (w.address < watch + size && watch < w.address + w.length)
            return static_cast<int>(i);
    }
    return -1;
}

unitTests:
TEST("the example") { CHECK_EQ(firstHit({ { 0x1000, 8 }, { 0x100C, 4 }, { 0x1004, 8 } }, 0x1008, 4), 2); }
TEST("an exact match") { CHECK_EQ(firstHit({ { 0x2000, 4 } }, 0x2000, 4), 0); }
TEST("one byte inside") { CHECK_EQ(firstHit({ { 0x200B, 1 } }, 0x2008, 4), 0); }
TEST("a big write covering everything") { CHECK_EQ(firstHit({ { 0x0, 0x10000 } }, 0x2008, 8), 0); }
TEST("ends exactly where the watch starts") { CHECK_EQ(firstHit({ { 0x1FF8, 8 } }, 0x2000, 8), -1); }
TEST("starts exactly where the watch ends") { CHECK_EQ(firstHit({ { 0x2008, 8 } }, 0x2000, 8), -1); }
TEST("first of several hits") { CHECK_EQ(firstHit({ { 0x10, 1 }, { 0x2001, 1 }, { 0x2002, 1 } }, 0x2000, 4), 1); }
TEST("nothing written") { CHECK_EQ(firstHit({}, 0x2000, 4), -1); }
TEST("empty writes touch nothing") { CHECK_EQ(firstHit({ { 0x2000, 0 } }, 0x2000, 4), -1); }

